import { EmptyState } from "@/components/design-for-ai/empty-state";

export function Results({ query, items }) {
  if (items.length) return <List items={items} />;
  return (
    <EmptyState
      variant="search"
      query={query}
      suggestions={["invoices", "Q3 report"]}
      onSuggestion={setQuery}
      secondary={{ label: "Clear search", onClick: () => setQuery("") }}
    />
  );
}
